// Airline policy documents split into chunks
// Each chunk will be embedded separately into Pinecone

const policies = [
  {
    id: "policy-1",
    text: "BASIC_ECONOMY fare rules: No changes allowed after booking. No date changes. No route changes. No seat selection. No refunds. Boarding is last priority. Baggage: 1 personal item only, no carry-on included."
  },
  {
    id: "policy-2", 
    text: "FLEXIBLE fare rules: Free date changes allowed up to 2 hours before departure. Free route changes allowed. Seat selection included at no extra cost. Full refund available up to 24 hours before departure. Priority boarding included."
  },
  {
    id: "policy-3",
    text: "BUSINESS_CLASS fare rules: Unlimited free changes. Full refund anytime. Premium seat selection. First boarding group. 2 checked bags included. Lounge access included."
  },
  {
    id: "policy-4",
    text: "Waitlist policy: Passengers are added to waitlist when flight class is full. Priority is determined by loyalty tier first, then fare class, then booking time. GOLD loyalty tier gets highest priority. SILVER gets second priority. STANDARD gets lowest priority."
  },
  {
    id: "policy-5",
    text: "Refund policy: Refund requests are processed within 3 business days. If refund is not processed within 3 days it is escalated to senior ops team. Refunds go back to original payment method. Travel credits expire after 12 months."
  },
  {
    id: "policy-6",
    text: "Check-in policy: Online check-in opens 24 hours before departure. Passengers must check in at least 1 hour before departure. Failure to check in results in seat being released to standby passengers."
  },
  {
    id: "policy-7",
    text: "Overbooking policy: Flights may be overbooked by up to 10 percent of capacity. Volunteers who give up seats receive travel credit worth 200 percent of ticket value. Involuntary denied boarding receives cash compensation per regulations."
  },
  {
    id: "policy-8",
    text: "Fraud policy: Passengers found with overlapping bookings on same time window will have duplicate bookings cancelled. First booking is kept. Repeat violations result in account suspension. Refunds are not provided for cancelled fraud bookings."
  }
];

// Return each policy as a separate item
return policies.map(p => ({ json: p }));

// Get all items passed into this node
const embeddingItems = $input.all();

// Get all policy docs from earlier node
const policyItems = $('Policy Documents').all();

// Process each item separately
const results = [];

for (let i = 0; i < embeddingItems.length; i++) {
  const embedding = embeddingItems[i].json.embedding;
  const policyId = policyItems[i].json.id;
  const policyText = policyItems[i].json.text;

  results.push({
    json: {
      body: JSON.stringify({
        vectors: [
          {
            id: policyId,
            values: embedding,
            metadata: {
              text: policyText,
              id: policyId
            }
          }
        ],
        namespace: ""
      })
    }
  });
}

return results;
